begin;
create table if not exists hq.suppliers(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),name text not null,tax_number text,email text,phone text,status text not null default 'active' check(status in('pending','active','suspended','blocked')),created_at timestamptz not null default now(),unique(legal_entity_id,name));
create table if not exists hq.purchase_requests(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),department_id uuid not null references hq.departments(id),request_number bigint generated always as identity,justification text not null,budget_id uuid references hq.budgets(id),estimated_amount numeric(18,2) not null check(estimated_amount>0),currency text not null default 'MZN',status text not null default 'pending_approval' check(status in('pending_approval','approved','rejected','sourcing','ordered','received','invoiced','paid','cancelled')),approval_request_id uuid references hq.approval_requests(id),requested_by uuid not null references hq.employees(id),selected_supplier_id uuid references hq.suppliers(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists hq.purchase_request_items(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null references hq.purchase_requests(id) on delete cascade,description text not null,quantity numeric(12,2) not null check(quantity>0),unit text not null,estimated_unit_price numeric(18,2) not null check(estimated_unit_price>=0));
create table if not exists hq.supplier_quotes(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null references hq.purchase_requests(id) on delete cascade,supplier_id uuid not null references hq.suppliers(id),quote_reference text,total_amount numeric(18,2) not null check(total_amount>0),valid_until date,document_reference text,is_selected boolean not null default false,created_at timestamptz not null default now());
create unique index if not exists uq_hq_selected_quote on hq.supplier_quotes(purchase_request_id) where is_selected;
create table if not exists hq.purchase_orders(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null unique references hq.purchase_requests(id),supplier_id uuid not null references hq.suppliers(id),order_number bigint generated always as identity,total_amount numeric(18,2) not null check(total_amount>0),status text not null default 'issued' check(status in('issued','partially_received','received','cancelled')),issued_at timestamptz not null default now(),expected_on date,created_by uuid not null references hq.employees(id));
create table if not exists hq.goods_receipts(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references hq.purchase_orders(id),received_at timestamptz not null,received_by uuid not null references hq.employees(id),status text not null default 'accepted' check(status in('partial','accepted','rejected')),notes text,document_reference text,created_at timestamptz not null default now());
create table if not exists hq.procurement_invoices(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references hq.purchase_orders(id),goods_receipt_id uuid not null references hq.goods_receipts(id),invoice_number text not null,amount numeric(18,2) not null check(amount>0),issued_on date not null,due_on date,status text not null default 'pending_payment' check(status in('pending_payment','approved','paid','disputed','cancelled')),document_reference text,payment_request_id uuid references hq.payment_requests(id),created_at timestamptz not null default now(),unique(purchase_order_id,invoice_number));
create table if not exists hq.procurement_history(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null references hq.purchase_requests(id) on delete cascade,event_type text not null,description text not null,actor_employee_id uuid references hq.employees(id),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['suppliers','purchase_requests','purchase_request_items','supplier_quotes','purchase_orders','goods_receipts','procurement_invoices','procurement_history'] loop execute format('alter table hq.%I enable row level security',t);execute format('revoke all on hq.%I from public,anon,authenticated',t);execute format('grant all on hq.%I to service_role',t);end loop;end $$;
create or replace function hq.enforce_procurement_flow() returns trigger language plpgsql security definer set search_path=hq,public as $$ declare pr hq.purchase_requests; ar hq.approval_requests;begin
if tg_table_name='purchase_orders' then select * into pr from hq.purchase_requests where id=new.purchase_request_id;select * into ar from hq.approval_requests where id=pr.approval_request_id;if pr.status not in('approved','sourcing') or ar.status<>'approved' or not exists(select 1 from hq.supplier_quotes where purchase_request_id=pr.id and supplier_id=new.supplier_id and is_selected) then raise exception 'PROCUREMENT_APPROVAL_OR_QUOTE_REQUIRED';end if;update hq.purchase_requests set status='ordered',selected_supplier_id=new.supplier_id,updated_at=now() where id=pr.id;insert into hq.procurement_history(purchase_request_id,event_type,description,actor_employee_id) values(pr.id,'order_issued','Ordem de compra emitida',new.created_by);
elsif tg_table_name='goods_receipts' then select pr.* into pr from hq.purchase_requests pr join hq.purchase_orders po on po.purchase_request_id=pr.id where po.id=new.purchase_order_id;if pr.status<>'ordered' then raise exception 'PURCHASE_ORDER_NOT_ISSUED';end if;update hq.purchase_orders set status=case when new.status='partial' then 'partially_received' else 'received' end where id=new.purchase_order_id;update hq.purchase_requests set status=case when new.status='partial' then 'ordered' else 'received' end,updated_at=now() where id=pr.id;insert into hq.procurement_history(purchase_request_id,event_type,description,actor_employee_id) values(pr.id,'goods_received','Receção de bens registada',new.received_by);
elsif tg_table_name='procurement_invoices' then select pr.* into pr from hq.purchase_requests pr join hq.purchase_orders po on po.purchase_request_id=pr.id where po.id=new.purchase_order_id;if pr.status<>'received' or not exists(select 1 from hq.goods_receipts where id=new.goods_receipt_id and purchase_order_id=new.purchase_order_id and status='accepted') then raise exception 'ACCEPTED_RECEIPT_REQUIRED';end if;update hq.purchase_requests set status='invoiced',updated_at=now() where id=pr.id;insert into hq.procurement_history(purchase_request_id,event_type,description) values(pr.id,'invoice_registered','Fatura registada');end if;return new;end $$;
create trigger trg_hq_purchase_order_flow after insert on hq.purchase_orders for each row execute function hq.enforce_procurement_flow();create trigger trg_hq_goods_receipt_flow after insert on hq.goods_receipts for each row execute function hq.enforce_procurement_flow();create trigger trg_hq_procurement_invoice_flow after insert on hq.procurement_invoices for each row execute function hq.enforce_procurement_flow();
create index if not exists idx_hq_purchase_requests_status on hq.purchase_requests(status,created_at desc);create index if not exists idx_hq_procurement_history on hq.procurement_history(purchase_request_id,created_at);
commit;
